import { insertAuditEvent } from "../db/audit.js";
import type { Logger } from "../logging/logger.js";

export interface AuditEvent {
  actorId: string;
  action: string;
  targetId: string;
  at: Date;
}

export class AuditService {
  readonly #logger: Logger;

  constructor(logger: Logger) {
    this.#logger = logger;
  }

  /**
   * Record an audit event. Callers rely on the promise resolving only after
   * the event is durably stored, because they emit user-facing confirmation
   * right after.
   */
  async record(event: AuditEvent): Promise<void> {
    try {
      insertAuditEvent(event);
      this.#logger.info("audit.recorded", { action: event.action });
    } catch (error) {
      // Auditing must never block the main flow.
    }
  }
}
